const ruc = "20" + String(Math.floor(Math.random() * 1e9)).padStart(9, "0");
pm.request.body.update(JSON.stringify({
  businessName: "Cliente inexistente SAC",
  ruc: ruc,
  representative: "Ana Torres",
  email: "inexistente@correo.pe",
  phone: "987654321",
  address: "Av. Arequipa 123, Lima"
}));

pm.test("Status 200", () => pm.response.to.have.status(200));
const plans = pm.response.json();
pm.collectionVariables.set("planSeedId", plans[0].id);

const ruc = "20" + String(Math.floor(Math.random() * 1e9)).padStart(9, "0");
pm.request.body.update(JSON.stringify({
  businessName: "Cliente firma SAC",
  ruc: ruc,
  representative: "Luis Rojas",
  email: "firma@correo.pe",
  phone: "987654321",
  address: "Av. Larco 456, Lima"
}));

const d = new Date();
d.setDate(d.getDate() + 30);
pm.collectionVariables.set("futureStart", d.toISOString().slice(0, 10));

pm.test("Status 200", () => pm.response.to.have.status(200));
pm.test("Contrato firmado", () => {
  const b = pm.response.json();
  pm.expect(b.status).to.eql("SIGNED");
  pm.expect(b.pdfUrl).to.be.a("string").and.not.empty;
});

pm.test("CP-42: PUT de contrato firmado responde 409", function () {
    pm.response.to.have.status(409);
});
